questionvariables.text:
aa:rand(3)+1;
bb:rand(2)+3;
cc:rand(2)+1;
dd:rand(3)+4;
total: aa+bb+cc+dd;
list_H: makelist(H, i, 1, aa);
list_A: makelist(A, i, 1, bb);
list_C: makelist(C, i, 1, cc);
list_M: makelist(M, i, 1, dd);
list:append(list_H,list_A,list_C,list_M);
angle_H: round((aa*360)/total);
angle_A: round((bb*360)/total);
angle_C: round((cc*360)/total);
